import itertools

def solve_game(S):
    S = tuple(sorted(S))

    # Check termination conditions
    if len(S) == 0:
        return 0

    max_val = max(S)
    sum_others = sum(S) - max_val
    if max_val > sum_others:
        return len(S)

    if all(x == 0 for x in S):
        return len(S)

    # Game state caching
    memo = {}
    def minimax(state):
        state = tuple(sorted(state))
        if state in memo:
            return memo[state]

        # Check termination
        if not state: return 0
        m = max(state)
        s_others = sum(state) - m
        if m > s_others:
            return len(state)
        if all(x == 0 for x in state):
            return len(state)

        # Player A's turn to choose x, y
        # A wants to maximize the result
        best_a = -float('inf')

        # Try all possible pairs (x, y)
        pairs = list(itertools.combinations(range(len(state)), 2))
        for i, j in pairs:
            x, y = state[i], state[j]

            # Player B's turn to choose x+y or |x-y|
            # B wants to minimize the result
            res_plus = minimax(tuple(sorted(list(state[:i] + state[i+1:j] + state[j+1:]) + [x + y])))
            res_minus = minimax(tuple(sorted(list(state[:i] + state[i+1:j] + state[j+1:]) + [abs(x - y)])))

            res_b = min(res_plus, res_minus)
            best_a = max(best_a, res_b)

        memo[state] = best_a
        return best_a

    return minimax(S)

for n in range(1, 11):
    print(f"N={n}: {solve_game(tuple([1]*n))}")

